'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const K = nextInt();

const prices = new Int32Array(K);
for (let i = 0; i < K; i++) prices[i] = nextInt();

const edgeV = new Int32Array(M);
const edgeU = new Int32Array(M);
const edgeType = new Int32Array(M);
const nextEdge = new Int32Array(M);
const colorHead = new Int32Array(K);
colorHead.fill(-1);

for (let i = 0; i < M; i++) {
  const v = nextInt() - 1;
  const u = nextInt() - 1;
  const t = nextInt() - 1;
  edgeV[i] = v;
  edgeU[i] = u;
  edgeType[i] = t;
  nextEdge[i] = colorHead[t];
  colorHead[t] = i;
}

const localV = new Int32Array(M);
const localU = new Int32Array(M);
const maxNodes = N + M;
const head = new Int32Array(maxNodes);
head.fill(-1);

const to = new Int32Array(4 * M);
const nextArc = new Int32Array(4 * M);
const weight = new Int32Array(4 * M);
let arcCount = 0;
let nodeCount = N;

function addArc(from, dest, cost) {
  to[arcCount] = dest;
  weight[arcCount] = cost;
  nextArc[arcCount] = head[from];
  head[from] = arcCount++;
}

for (let color = 0; color < K; color++) {
  if (colorHead[color] === -1) continue;

  const vertexMap = new Map();
  const parent = [];
  const size = [];

  function getLocalId(vertex) {
    let id = vertexMap.get(vertex);
    if (id === undefined) {
      id = parent.length;
      vertexMap.set(vertex, id);
      parent.push(id);
      size.push(1);
    }
    return id;
  }

  function find(x) {
    let root = x;
    while (parent[root] !== root) root = parent[root];
    while (parent[x] !== x) {
      const p = parent[x];
      parent[x] = root;
      x = p;
    }
    return root;
  }

  for (let e = colorHead[color]; e !== -1; e = nextEdge[e]) {
    const a = getLocalId(edgeV[e]);
    const b = getLocalId(edgeU[e]);
    localV[e] = a;
    localU[e] = b;

    let ra = find(a);
    let rb = find(b);
    if (ra !== rb) {
      if (size[ra] < size[rb]) {
        const tmp = ra;
        ra = rb;
        rb = tmp;
      }
      parent[rb] = ra;
      size[ra] += size[rb];
    }
  }

  const componentId = new Int32Array(parent.length);
  componentId.fill(-1);

  for (let i = 0; i < parent.length; i++) {
    const root = find(i);
    if (componentId[root] === -1) componentId[root] = nodeCount++;
  }

  const price = prices[color];
  for (let e = colorHead[color]; e !== -1; e = nextEdge[e]) {
    const compV = componentId[find(localV[e])];
    const compU = componentId[find(localU[e])];

    addArc(edgeV[e], compV, price);
    addArc(compV, edgeV[e], 0);
    addArc(edgeU[e], compU, price);
    addArc(compU, edgeU[e], 0);
  }
}

const start = nextInt() - 1;
const target = nextInt() - 1;

const dist = new Float64Array(nodeCount);
dist.fill(Infinity);
dist[start] = 0;

const base = nodeCount + 1;
const heap = [];

function heapPush(key) {
  let i = heap.length;
  heap.push(key);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heap[p] <= key) break;
    heap[i] = heap[p];
    i = p;
  }
  heap[i] = key;
}

function heapPop() {
  const min = heap[0];
  const last = heap.pop();
  if (heap.length > 0) {
    let i = 0;
    while (true) {
      const left = i * 2 + 1;
      if (left >= heap.length) break;
      const right = left + 1;
      const child = right < heap.length && heap[right] < heap[left] ? right : left;
      if (heap[child] >= last) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
  }
  return min;
}

heapPush(start);

while (heap.length > 0) {
  const key = heapPop();
  const d = Math.floor(key / base);
  const u = key - d * base;

  if (d !== dist[u]) continue;
  if (u === target) break;

  for (let e = head[u]; e !== -1; e = nextArc[e]) {
    const v = to[e];
    const nd = d + weight[e];
    if (nd < dist[v]) {
      dist[v] = nd;
      heapPush(nd * base + v);
    }
  }
}

console.log(Number.isFinite(dist[target]) ? String(dist[target]) : '-1');
